async function listener(
  _event,
  account,
  { id, name, data },
  tab,
  relatedFileInfo
) {
  if (fire.wakeup) {
    await fire.wakeup();
  }
  tab = tab ? tabManager.convert(tab) : null;
  account = convertCloudFileAccount(account);
  return fire.async(account, { id, name, data }, tab, relatedFileInfo);
